$ErrorActionPreference='Stop'
$packet='Z:/src/RedSalamander/Specs/TestRuns/Local-x64/Navigation/2026-10-20_DebugSortingRowMoves'
$summary=Get-Content (Join-Path $packet 'performance-comparison.json') -Raw|ConvertFrom-Json
$invariant=[Globalization.CultureInfo]::InvariantCulture
function Ms($value){([decimal]$value/1000).ToString('0.000',$invariant)}
$text=[Collections.Generic.List[string]]::new()
foreach($line in @('# I43 Debug sorting row movement','','Fresh same-machine baseline/candidate pairs use the unchanged 5,000-file corpus, ten requests and five repetitions per profile. Every accepted phase passes five cases and retains all 50 request timings. Selection is by case/observer predicates before inspecting latency.','','The optimization sorts reusable row indices with the existing comparator, then applies whole-row permutation cycles. Owned strings/layouts and selection/current state follow their original identities. Globally checked Debug iterators remain enabled. The Windows comparison helper, rank preparation, complete production comparator, sort threshold, benchmark fixture and build-property inputs are unchanged; see [source checks](ordering-preservation-source-checks.json).','','## Core ordering and complete sort call','','Milliseconds, median [minimum - maximum]. Stage records also include setup and fixture restoration; counts are not cold-open trial counts. Separate stage medians must not be added.','','| Profile / stage | Baseline ms | Candidate ms | Median change |','| --- | --- | --- | --- |')){$text.Add($line)}
foreach($configuration in @('Debug','Release')){
 $pair=$summary.pairs.$configuration
 foreach($stage in @('ordering','apply_current_sort')){
  $b=$pair.$stage.baseline;$c=$pair.$stage.candidate
  $change=100*($c.median_us-$b.median_us)/$b.median_us
  $label=if($stage-eq'ordering'){'OrderItems'}else{'ApplyCurrentSort'}
  $text.Add("| $configuration $label | $(Ms $b.median_us) [$(Ms $b.min_us) - $(Ms $b.max_us)] | $(Ms $c.median_us) [$(Ms $c.min_us) - $(Ms $c.max_us)] | $($change.ToString('0.00',$invariant))% |")
 }
}
foreach($line in @('','## Total sort-request latency','','Milliseconds, median of all five observations for each request. These include layout, rendering, pumping and settling. The first Name Ascending request begins already sorted and can be a SetSort no-op. All samples and ranges remain in [performance-comparison.json](performance-comparison.json).','','| Request | Debug baseline / candidate | Debug change | Release baseline / candidate | Release change |','| --- | --- | --- | --- | --- |')){$text.Add($line)}
for($index=0;$index-lt10;$index++){
 $d=$summary.pairs.Debug.requests[$index];$r=$summary.pairs.Release.requests[$index]
 $label="$($d.key) $($d.direction)";if($d.key-eq'None'){$label+=' ('+$(if($index-eq4){'first'}else{'last'})+')'}
 $text.Add("| $label | $(Ms $d.baseline_median_us) / $(Ms $d.candidate_median_us) | $($d.change_percent.ToString('0.00',$invariant))% | $(Ms $r.baseline_median_us) / $(Ms $r.candidate_median_us) | $($r.change_percent.ToString('0.00',$invariant))% |")
}
$dImproved=@($summary.pairs.Debug.requests|Where-Object change_percent -lt 0).Count
$rImproved=@($summary.pairs.Release.requests|Where-Object change_percent -lt 0).Count
$text.Add('');$text.Add("Debug request medians decreased for $dImproved/10 requests; Release for $rImproved/10. Core ordering and complete request latency are separate claims. Higher request medians remain visible; no sample is removed or rebaselined. Initial worker enumeration sorting is unchanged.")
$text.Add('');$text.Add('Release Extension Ascending is the largest total-request increase: 28.266 ms to 49.861 ms (+76.399%), with overlapping five-sample ranges of 25.134-69.504 ms and 47.696-79.084 ms. Size Descending, Time Ascending and the last None request also increase. The measured core improves in both profiles, and all Debug request medians improve; this does not qualify Release rendered-latency non-regression. A separate counterbalanced rendering/settling investigation is required before that broader claim. No causal explanation is inferred from these samples alone.')
foreach($line in @('','## Pairing, observations and scope','','Both Debug and Release pair the same isolated checkout at `Z:/src/RedSalamander-worktrees/debug-sort-row-moves-validation`. Concurrent ViewerSpace edits invalidated the main v2 build, so its unrelated work was preserved and excluded from final pairing. Earlier main builds/tests and the clean main Debug baseline remain supplemental history. Both isolated baselines ran on the unchanged algorithm before the frozen sorting patch was applied there. The final candidate uses one lazy staging row across cycles. Each pair has matching checkout, fixture, toolchain, dependency, build flags and observer identities.','','| Profile / phase | Run ID | Receipt | Build overlap polls | Max sample gap | Observer CPU / elapsed |','| --- | --- | --- | --- | --- | --- |')){$text.Add($line)}
foreach($configuration in @('Debug','Release')){
 $pair=$summary.pairs.$configuration
 foreach($role in @('baseline','candidate')){
  $phase=$pair.$role;$o=Get-Content (Join-Path $packet "$phase/observation.json") -Raw|ConvertFrom-Json;$p=$summary.phases.$phase
  $elapsed=(([DateTime]$o.runner_ended_utc).ToUniversalTime()-([DateTime]$o.runner_started_utc).ToUniversalTime()).TotalSeconds
  $text.Add("| $configuration $role ($phase) | $($p.run_id) | $($p.receipt_id) | $($o.measurement_contaminated_polls) | $($o.maximum_measurement_gap_ms) ms | $(Ms $o.measurement_observer_cpu_ms) s / $($elapsed.ToString('0.000',$invariant)) s |")
 }
 $c=$summary.phases.($pair.candidate)
 $text.Add('');$text.Add("$configuration candidate counters: $($c.payload_move_records) movement records, minimum $($c.payload_moves_min) and maximum $($c.payload_moves_max) payload moves; retained index scratch $($c.index_scratch_bytes_min)-$($c.index_scratch_bytes_max) bytes. All records satisfy the linear movement and capacity bounds.");$text.Add('')
}
foreach($line in @('The observer requires a separate 30-second quiet gate and samples the entire canonical runner window, nominally every 200 ms. Exact dead-parent reusable MSBuild nodes are excluded only after 30 seconds of unchanged CPU counters; any resumed CPU activity makes them blockers. The unrelated GIGABYTE GCC executable is excluded by exact verified identity. Compiler detection is otherwise unconditional; unknown orchestration shells are retried and block once persistent for 1,000 ms.','','This establishes no observed background build overlap, not a completely idle host or a lossless process-start audit. Short-lived processes can fit between snapshots; short unresolved shells and observer CPU cost are retained. No privileged event subscription was requested. Each rejected benchmark and every gate-only retirement is retained separately. Historical October 17 contended measurements are not the baseline for these pairs.','','## Correctness and qualification','','The final isolated x64 Debug and Release solution builds are test-enabled and complete with zero warnings/errors. The six focused cases pass in both final executions (functional-final-debug and functional-final-release): natural-name contracts, bounded current memory, navigation roundtrip, refresh/filter selection, visibility/selection restoration, and current/selection/removal state. The expanded real reorder test covers all six keys, both directions, three cache modes and four input permutations; all 720 six-row permutations; owned DirectWrite layouts/strings; empty/singleton models; the actual sequential/parallel boundary; scratch reuse/release; and full-width numeric extremes.','','All 289 focused tooling/source-contract Pester tests pass on the final isolated source. Specification/tool inventories, changed-range formatting, archive validation, and independent raw evidence verification are recorded alongside this packet. This is focused sorting qualification; it does not establish Full, ARM64, ASan or process-wide memory/performance qualification.','','The shared sandbox audit reports the existing 41 unexpected run directories. Original aggregate results retain every reason. They were preserved; passing native cases and exit codes do not imply a clean sandbox audit.','','## Time and Size versus natural sorting','','Name and Extension use Windows natural ordering. Time uses signed 64-bit modification timestamps; Size uses unsigned 64-bit byte counts for files, while folders use natural names. Attributes use numeric DWORD flags. Main-pane equal metadata values use natural names, then ordinal spelling and stable source order. Find Size/Modified remain numeric and retain arrival order on equal values. Date formatting and size separators are not sort keys.','','## Evidence retention','','Original case verdicts, reasons, traces, aggregate results, immutable receipts and claim-bearing metric rows are retained. All 50 request samples and every relevant sorting metric remain in original row order; all benchmark snapshots and the final gate interval are retained. Larger raw streams and complete build logs remain under `Z:/RedSalamander.Perf/evidence/natural-sort-row-reorder-2026-10-20`, with SHA-256, byte/row counts and exact extraction policy in [artifact-bindings.json](artifact-bindings.json). See [independent verification](independent-evidence-verification.json).','','The archived scripts describe this measured snapshot; they are not new supported repository commands. Canonical runtime command for each profile:','','```powershell','Tools/Run-AllTests.ps1 -Suite Commands -Configuration Debug -SkipBuild -CaseFilter folderView_perf_sort_toggle_stress -SelfTestRepeat 5','Tools/Run-AllTests.ps1 -Suite Commands -Configuration Release -SkipBuild -CaseFilter folderView_perf_sort_toggle_stress -SelfTestRepeat 5','```')){$text.Add($line)}
$text.Add('')
$text.Add('The complete focused commands traces and native verdicts/reasons are unabridged. Verbose functional application traces retain the first/last 20 lines and every selftest/assert/error/warning/failure line in original order; the full application traces remain externally digest-bound. Gate-only retirements retain eight available tail lines for diagnosis and make no quiet-window qualification claim. All selected and rejected benchmark measurement snapshots and relevant metrics remain complete.')
$text.Add('')
$text.Add('Final artifact-lock readback verifies the current isolated executable/runtime closure and exact compiled sorting C++ inputs in both profiles; the main checkout contains the same three C++ files. See [current identities](final-identities.json). Main Release was running during closeout and was left undisturbed. Qualified Debug/Release binaries remain in the isolated checkout. Later plan/evidence closeout changes documentation only. The [completed I43 record](../../../../Plans/Done/UI_DebugSortingRowMoves_2026-10-20.md) retains this scope and the unresolved broader Release timing question.')
[IO.File]::WriteAllLines((Join-Path $packet 'README.md'),$text.ToArray(),[Text.UTF8Encoding]::new($false))
